use super::*;
use crate::test_retirement::close_original;
use semio_framework_value_native_owned::{native_decoding::NativeDecodeAllocation, native_decoding::NativeDecodeAllocationPort, native_decoding::NativeDecodeRetirementRecipient};
#[derive(Clone,Copy)]struct OriginalPages<'a>{pages:&'a[&'a[u8]],page_bytes:usize,identity:OriginalWireSourceIdentity}
impl RetainedWireByteSource for OriginalPages<'_>{fn original_source_identity(&self)->OriginalWireSourceIdentity{self.identity}fn byte_at(&self,index:usize)->Option<u8>{if index>=self.identity.extent{return None}self.pages.get(index/self.page_bytes)?.get(index%self.page_bytes).copied()}}
fn observe<T>(operation:impl FnOnce()->T)->(T,usize,usize){semio_framework_trace_memory_testing::observe_backing(operation)}
fn receipt(owner:&mut RetainedHistorySourceDecode,g:RetainedCloneGrant,born:usize,released:usize){let(issued,p)=owner.take_receipt().unwrap();assert_eq!(issued,g);assert!(p.fits(g));assert_eq!((born,released),(p.retained_capacity_bytes,p.released_bytes));}
fn hex(value:&str)->Vec<u8>{value.as_bytes().chunks_exact(2).map(|pair|u8::from_str_radix(std::str::from_utf8(pair).unwrap(),16).unwrap()).collect()}
fn id(body:&mut Vec<u8>,value:&str){body.push(0);protocol::codec::write_varint_u64(body,value.len()as u64);body.extend_from_slice(value.as_bytes());}
async fn original_bytes(law:&serde_json::Value,conflicts:&serde_json::Value,transitions:&serde_json::Value,trial:&str)->Vec<u8>{let options=protocol::format::WriteOptions{required_flags:protocol::REQUIRED_HASH_CHAIN,optional_flags:protocol::OPTIONAL_CANONICAL};let mut writer=protocol::format::SprWriter::begin(Vec::new(),&options).await.unwrap();for row in law["records"].as_array().unwrap(){writer.write_record(row["kind"].as_u64().unwrap()as u8,row["flags"].as_u64().unwrap()&2!=0,&hex(row["payloadHex"].as_str().unwrap()),protocol::codec::ids::CodecId(0)).await.unwrap();}let declaration=&law["nativeTrials"]["transition"];let payload_case=declaration[if trial=="malformed-transition"{"malformedPayloadCase"}else{"canonicalPayloadCase"}].as_str().unwrap();let row=transitions["cases"].as_array().unwrap().iter().find(|row|row["id"].as_str()==Some(payload_case)).unwrap();let payload=hex(row["payloadHex"].as_str().unwrap());let mut body=vec![1];id(&mut body,declaration["id"].as_str().unwrap());id(&mut body,declaration["actor"].as_str().unwrap());for value in declaration["hlt"].as_array().unwrap(){protocol::codec::write_varint_u64(&mut body,value.as_u64().unwrap())}body.push(0);protocol::codec::write_varint_u64(&mut body,payload.len()as u64);body.extend_from_slice(&payload);writer.write_record(super::super::REC_TRANSITION,false,&body,protocol::codec::ids::CodecId(0)).await.unwrap();let mut body=vec![1];protocol::codec::write_varint_u64(&mut body,conflicts["conflicts"].as_array().unwrap().len()as u64);for row in conflicts["conflicts"].as_array().unwrap(){let bytes=hex(row["wireHex"].as_str().unwrap());body.extend_from_slice(&bytes);}writer.write_record(super::super::REC_CONFLICT,false,&body,protocol::codec::ids::CodecId(0)).await.unwrap();if trial=="duplicate-edit"{let row=law["records"].as_array().unwrap().iter().find(|row|row["kind"].as_u64()==Some(u64::from(protocol::REC_EDIT))).unwrap();writer.write_record(protocol::REC_EDIT,true,&hex(row["payloadHex"].as_str().unwrap()),protocol::codec::ids::CodecId(0)).await.unwrap();}if trial=="replace-viewer-composition"{for kind in[super::super::REC_VIEWER,super::super::REC_COMPOSITION]{let row=law["records"].as_array().unwrap().iter().find(|row|row["kind"].as_u64()==Some(u64::from(kind))).unwrap();writer.write_record(kind,false,&hex(row["payloadHex"].as_str().unwrap()),protocol::codec::ids::CodecId(0)).await.unwrap();}}writer.commit().await.unwrap();writer.into_sink().await}
#[test]fn original_history_source_native_assembles_verified_fields_actual_edit_ordinals_and_paid_faults(){
 let law:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap();let conflicts:serde_json::Value=serde_json::from_str(include_str!("../../⚔️conflict/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();let transitions:serde_json::Value=serde_json::from_str(include_str!("../../../../../../../../🔨️modules/📡️replication/🔗️causal/🧪️tests/🧫️fixtures/🧫️history-transition/🔣️.json")).unwrap();let limits:HistoryReadLimits=serde_json::from_value(law["limits"].clone()).unwrap();let control_limit=law["control"]["maximumAllocationBytes"].as_u64().unwrap()as usize;let axes=&law["grant"];let n=|key:&str|axes[key].as_u64().unwrap()as usize;let g=RetainedCloneGrant{maximum_items:n("items"),maximum_copy_bytes:n("copyBytes"),maximum_capacity_bytes:n("capacityBytes"),maximum_release_bytes:n("releaseBytes"),maximum_depth:n("depth")};
 for trial in law["nativeTrials"]["cases"].as_array().unwrap(){let kind=trial["kind"].as_str().unwrap();let committed=semio_framework_async::poll::resolve_ready(original_bytes(&law,&conflicts,&transitions,kind));let mut original=vec![0xaa];original.extend_from_slice(&committed);let end=original.len();original.push(0xbb);for paged in[false,true]{let page_bytes=if paged{law["source"]["pageBytes"].as_u64().unwrap()as usize}else{original.len()};let pages=original.chunks(page_bytes).collect::<Vec<_>>();let identity=OriginalWireSourceIdentity{address:original.as_ptr()as usize,extent:original.len(),authority:if paged{Some((43,7))}else{None}};let source=OriginalPages{pages:&pages,page_bytes,identity};for cancellation in law["nativeTrials"]["cancelAt"].as_array().unwrap(){let cancellation=cancellation.as_u64().unwrap()as usize;let admitted=std::sync::atomic::AtomicUsize::new(0);let mut allocation=|request:NativeDecodeAllocation|{assert_eq!(request.owned_bytes,admitted.load(std::sync::atomic::Ordering::SeqCst));assert!(request.bytes<=g.maximum_capacity_bytes);assert!(request.maximum_bytes<=control_limit);assert_eq!(request.next_owned_bytes,request.owned_bytes+request.bytes);admitted.store(request.next_owned_bytes,std::sync::atomic::Ordering::SeqCst);Ok(())};let port:&mut NativeDecodeAllocationPort<'_>=&mut allocation;let mut callback=|_|true;let mut retirement=NativeDecodeRetirementRecipient::new();let mut control=NativeDecodeControl::new_forwarded(control_limit,&mut callback,port);control.install_retirement_recipient(&mut retirement).unwrap();
  for denied in[RetainedCloneGrant{maximum_items:0,..g},RetainedCloneGrant{maximum_depth:1,..g}]{let(owner,born,released)=observe(||RetainedHistorySourceDecode::admit(&source,(1,end),limits,true,&control,denied).unwrap());assert!(owner.is_none());assert_eq!((born,released),(0,0));}
  let(owner,born,released)=observe(||RetainedHistorySourceDecode::admit(&source,(1,end),limits,true,&control,g).unwrap());assert_eq!((born,released),(0,0));let mut owner=owner.unwrap();receipt(&mut owner,g,born,released);assert_eq!(owner.original_range(),(1,end));for changed_identity in[OriginalWireSourceIdentity{address:identity.address+1,..identity},OriginalWireSourceIdentity{extent:identity.extent-1,..identity},OriginalWireSourceIdentity{authority:Some((43,8)),..identity}]{let changed=OriginalPages{identity:changed_identity,..source};let(result,born,released)=observe(||owner.step(&changed,&mut control,g));assert!(result.is_err());assert_eq!((born,released),(0,0));assert!(owner.receipt().is_none());}let mut foreign_callback=|_|true;let mut foreign=NativeDecodeControl::new(control_limit,&mut foreign_callback);let(result,born,released)=observe(||owner.step(&source,&mut foreign,g));assert!(result.is_err());assert_eq!((born,released),(0,0));drop(foreign);
  let(mut births,mut releases)=(0,0);for _ in 0..cancellation{if owner.is_ready()||owner.fault().is_some(){break}let d=owner.demands(&source,&control,g.maximum_copy_bytes).unwrap();for(axis,denied)in[RetainedCloneGrant{maximum_items:0,..g},RetainedCloneGrant{maximum_depth:d.depth.saturating_sub(1),..g},RetainedCloneGrant{maximum_copy_bytes:0,..g},RetainedCloneGrant{maximum_capacity_bytes:d.capacity_bytes.saturating_sub(1),..g},RetainedCloneGrant{maximum_release_bytes:d.release_bytes.saturating_sub(1),..g}].into_iter().enumerate(){if axis==2&&d.copy_bytes==0||axis==3&&d.capacity_bytes==0||axis==4&&d.release_bytes==0{continue}let before=(owner.consumed_end(),control.owned_bytes());let(step,born,released)=observe(||owner.step(&source,&mut control,denied).unwrap());assert_eq!(step,RetainedHistorySourceStep::Blocked,"{kind} axis{axis} phase{} demand{d:?}",owner.phase);assert_eq!((born,released),(0,0));assert_eq!((owner.consumed_end(),control.owned_bytes()),before);assert!(owner.receipt().is_none());}let(step,born,released)=observe(||owner.step(&source,&mut control,g).unwrap());assert_ne!(step,RetainedHistorySourceStep::Blocked,"{kind} phase{}",owner.phase);receipt(&mut owner,g,born,released);births+=born;releases+=released;}
  if cancellation==100000&&trial["accept"].as_bool().unwrap(){assert!(owner.is_ready(),"{kind} phase{} fault{:?}",owner.phase,owner.fault());let mut log=None;let(moved,born,released)=observe(||owner.take_ready_into(&mut log,g).unwrap());assert!(moved);receipt(&mut owner,g,born,released);assert_eq!((born,released),(0,0));let value=log.as_ref().unwrap();let expected=&law["expected"];assert_eq!(value.doc_id,expected["docId"].as_str().unwrap());assert_eq!(value.schema,expected["schema"].as_str().unwrap());assert_eq!(value.edits.len(),2);for(index,edit)in value.edits.iter().enumerate(){assert_eq!(edit.id,expected["editIds"][index].as_str().unwrap());assert_eq!(edit.actor.as_ref().map(|a|a.as_str()),expected["actors"][index].as_str());assert_eq!(edit.ops[0].binary.as_ref().unwrap(),&hex(expected["binaryOpsHex"][index].as_str().unwrap()));assert_eq!(edit.meta.as_ref().unwrap()[0].base_version,expected["baseVersions"][index].as_u64().unwrap());}assert_eq!(value.viewer_line.as_deref(),expected["viewerLine"].as_str());assert_eq!(value.viewer_checkpoint.as_deref(),expected["viewerCheckpoint"].as_str());let composition=value.composition.as_ref().unwrap();let owner=composition.owner.as_ref().unwrap();assert_eq!([owner.0.as_str(),owner.1.as_str(),owner.2.as_str()],[expected["owner"][0].as_str().unwrap(),expected["owner"][1].as_str().unwrap(),expected["owner"][2].as_str().unwrap()]);assert_eq!(value.transitions.len(),1);assert_eq!(value.transitions[0].id,law["nativeTrials"]["transition"]["id"].as_str().unwrap());assert_eq!(value.conflicts.len(),2);assert_eq!(value.conflicts[1].edit_ids[0],expected["editIds"][0].as_str().unwrap());let(b,r)=close_original(log.take().unwrap(),&mut control,g);births+=b;releases+=r;}
  else{if cancellation==100000{assert!(owner.fault().is_some(),"{kind} did not retain its original refusal")}if owner.fault().is_some(){let mut error=None;let(moved,born,released)=observe(||owner.take_fault_into(&mut error,g).unwrap());assert!(moved);receipt(&mut owner,g,born,released);births+=born;releases+=released;let(b,r)=close_original(error.take().unwrap(),&mut control,g);births+=b;releases+=r;}owner.cancel();for _ in 0..100000{if owner.partial_is_receivable(){let mut partial=None;let(moved,born,released)=observe(||owner.take_partial_into(&mut partial,g).unwrap());assert!(moved);receipt(&mut owner,g,born,released);births+=born;releases+=released;let(b,r)=close_original(partial.take().unwrap(),&mut control,g);births+=b;releases+=r;break}if owner.fault().is_some(){let mut error=None;let(moved,born,released)=observe(||owner.take_fault_into(&mut error,g).unwrap());assert!(moved);receipt(&mut owner,g,born,released);births+=born;releases+=released;let(b,r)=close_original(error.take().unwrap(),&mut control,g);births+=b;releases+=r;continue}let(step,born,released)=observe(||owner.close_step(&source,&mut control,g).unwrap());assert_ne!(step,RetainedHistorySourceStep::Blocked,"{kind} cancellation{cancellation} phase{}",owner.phase);receipt(&mut owner,g,born,released);births+=born;releases+=released;}for _ in 0..16{if owner.terminal_is_empty(){break}let(step,born,released)=observe(||owner.close_step(&source,&mut control,g).unwrap());assert_ne!(step,RetainedHistorySourceStep::Blocked);receipt(&mut owner,g,born,released);births+=born;releases+=released;}}
  assert!(owner.terminal_is_empty());assert_eq!(births,releases,"{kind} cancellation{cancellation}");assert_eq!(control.owned_bytes(),admitted.load(std::sync::atomic::Ordering::SeqCst));let(_,born,released)=observe(||drop(owner));assert_eq!((born,released),(0,0));drop(control);assert!(retirement.terminal_is_empty());
 }}}
}
struct CancelledTurn(std::cell::Cell<bool>);
impl super::super::RetainedHistoryTurn for CancelledTurn{fn should_yield(&self)->bool{false}fn is_cancelled(&self)->bool{self.0.get()}}
fn assert_corpus_log(value:&HistoryLog,law:&serde_json::Value){
 let expected=&law["expected"];assert_eq!(value.doc_id,expected["docId"].as_str().unwrap());assert_eq!(value.schema,expected["schema"].as_str().unwrap());assert_eq!(value.edits.len(),2);
 for(index,edit)in value.edits.iter().enumerate(){assert_eq!(edit.id,expected["editIds"][index].as_str().unwrap());assert_eq!(edit.actor.as_ref().map(|a|a.as_str()),expected["actors"][index].as_str());assert_eq!(edit.ops[0].binary.as_ref().unwrap(),&hex(expected["binaryOpsHex"][index].as_str().unwrap()));assert_eq!(edit.meta.as_ref().unwrap()[0].base_version,expected["baseVersions"][index].as_u64().unwrap());}
 assert_eq!(value.viewer_line.as_deref(),expected["viewerLine"].as_str());assert_eq!(value.viewer_checkpoint.as_deref(),expected["viewerCheckpoint"].as_str());let owner=value.composition.as_ref().unwrap().owner.as_ref().unwrap();assert_eq!([owner.0.as_str(),owner.1.as_str(),owner.2.as_str()],[expected["owner"][0].as_str().unwrap(),expected["owner"][1].as_str().unwrap(),expected["owner"][2].as_str().unwrap()]);
 assert_eq!(value.transitions.len(),1);assert_eq!(value.transitions[0].id,law["nativeTrials"]["transition"]["id"].as_str().unwrap());assert_eq!(value.conflicts.len(),2);assert_eq!(value.conflicts[1].edit_ids[0],expected["editIds"][0].as_str().unwrap());
}
#[test]fn original_history_driver_settles_every_corpus_trial_over_granted_turns_and_cancellations(){
 let law:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap();let conflicts:serde_json::Value=serde_json::from_str(include_str!("../../⚔️conflict/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();let transitions:serde_json::Value=serde_json::from_str(include_str!("../../../../../../../../🔨️modules/📡️replication/🔗️causal/🧪️tests/🧫️fixtures/🧫️history-transition/🔣️.json")).unwrap();let limits:HistoryReadLimits=serde_json::from_value(law["limits"].clone()).unwrap();let control_limit=law["control"]["maximumAllocationBytes"].as_u64().unwrap()as usize;let axes=&law["grant"];let n=|key:&str|axes[key].as_u64().unwrap()as usize;let g=RetainedCloneGrant{maximum_items:n("items"),maximum_copy_bytes:n("copyBytes"),maximum_capacity_bytes:n("capacityBytes"),maximum_release_bytes:n("releaseBytes"),maximum_depth:n("depth")};
 for trial in law["nativeTrials"]["cases"].as_array().unwrap(){let kind=trial["kind"].as_str().unwrap();let committed=semio_framework_async::poll::resolve_ready(original_bytes(&law,&conflicts,&transitions,kind));let mut original=vec![0xaa];original.extend_from_slice(&committed);let end=original.len();original.push(0xbb);
  for paged in[false,true]{let page_bytes=if paged{law["source"]["pageBytes"].as_u64().unwrap()as usize}else{original.len()};let pages=original.chunks(page_bytes).collect::<Vec<_>>();let identity=OriginalWireSourceIdentity{address:original.as_ptr()as usize,extent:original.len(),authority:if paged{Some((43,7))}else{None}};let source=OriginalPages{pages:&pages,page_bytes,identity};
   for cancellation in law["nativeTrials"]["cancelAt"].as_array().unwrap(){let cancellation=cancellation.as_u64().unwrap()as usize;let mut driver=super::super::RetainedHistoryDecode::new((1,end),limits,true,control_limit).unwrap();let turn=CancelledTurn(std::cell::Cell::new(false));let mut history=None;let mut step=RetainedHistorySourceStep::Progress;
    for _ in 0..cancellation{step=driver.step(&source,&turn,g,&mut history).unwrap();if let Some((issued,paid))=driver.take_receipt(){assert_eq!(issued,g);assert!(paid.fits(g));}if matches!(step,RetainedHistorySourceStep::Ready|RetainedHistorySourceStep::Fault){break}}
    if cancellation==100000&&trial["accept"].as_bool().unwrap(){assert_eq!(step,RetainedHistorySourceStep::Ready,"{kind} fault{:?}",driver.fault());assert_corpus_log(history.as_ref().unwrap(),&law);assert!(driver.terminal_is_empty());}
    else{if cancellation==100000{assert!(driver.fault().is_some(),"{kind} did not retain its original refusal")}turn.0.set(true);if !driver.terminal_is_empty()&&history.is_none(){assert!(matches!(driver.step(&source,&turn,g,&mut history).unwrap(),RetainedHistorySourceStep::Blocked|RetainedHistorySourceStep::Fault))}for _ in 0..100000{if driver.terminal_is_empty(){break}let closed=driver.close_step(&source,&super::super::RetainedHistoryUninterrupted,g).unwrap();assert!(closed.progress().fits(g))}assert!(driver.terminal_is_empty(),"{kind} cancellation{cancellation}");}
   }}}
}
